#!/usr/bin/env bash
set -euo pipefail
python3 - <<'PY'
from pathlib import Path
from datetime import datetime,timezone
import hashlib,json,re,subprocess
cfg=Path('/root/cfg/workmate');out=cfg/'integrated-205/resume-baseline-v1.json';assert not out.exists()
sha=lambda b:hashlib.sha256(b).hexdigest()
old=json.loads((cfg/'integrated-202/network-baseline-v1.json').read_text());original=json.loads((cfg/'integrated-203/static-deployment-v1.json').read_text())
files={p:sha(Path(p).read_bytes()) for p in old['files']};assert files==old['files']
credentials={p:sha(Path(p).read_bytes()) for p in original['credential_hashes']};assert credentials==original['credential_hashes']
commands={}
for name,cmd in [('routes',['ip','-j','route','show','table','all']),('rules',['ip','-j','rule','show']),('iptables',['iptables-save']),('ip6tables',['ip6tables-save'])]:
 try:r=subprocess.run(cmd,capture_output=True,check=True,timeout=15)
 except (FileNotFoundError,subprocess.SubprocessError):commands[name]={'status':'unavailable'};continue
 data=r.stdout
 if name in ['iptables','ip6tables']:
  pattern=r'(?m)^(# (?:Generated by ip6?tables-save [^\n]+? on|Completed on) )[^\n]*$';text=data.decode();assert len(re.findall(pattern,text))>=2
  data=re.sub(pattern,lambda m:m.group(1)+'<generated timestamp>',text).encode()
 commands[name]={'status':'read','sha256':sha(r.stdout),'comparison_sha256':sha(data),'only_generated_comment_times_normalized':name in ['iptables','ip6tables']}
services={u:subprocess.check_output(['systemctl','show',u,'-p','ActiveState','-p','MainPID','-p','NRestarts','-p','WorkingDirectory'],text=True) for u in ['workmate-api.service','workmate-db.service','workmate-lan-proxy.service']}
assert 'WorkingDirectory=/opt/workmate/overlays/integrated-204-v2/backend' in services['workmate-api.service'] and all('ActiveState=active' in x for x in services.values())
source=Path('/home/carzygod/workmate-downloads-205-v1');manifest=json.loads((source/'manifest.json').read_text());assert manifest['stage']==205
for name,row in manifest['files'].items():assert (source/name).stat().st_size==row['bytes'] and sha((source/name).read_bytes())==row['sha256']
partial=Path('/opt/workmate/downloads/releases/20501');assert partial.is_dir() and not partial.is_symlink() and not (cfg/'integrated-205/downloads-v1/receipt.json').exists()
partial_files=[{'name':p.name,'bytes':p.stat().st_size,'sha256':sha(p.read_bytes())} for p in sorted(partial.iterdir())];assert {r['name'] for r in partial_files}.issubset(set(manifest['files']))
report={'stage':205,'at':datetime.now(timezone.utc).isoformat(),'status':'captured','scope':'Fresh authoritative preservation baseline before resumed application publication. Only this Workmate receipt is written; networking and services are read-only. Older interrupted evidence stays unchanged.','boot_id':Path('/proc/sys/kernel/random/boot_id').read_text().strip(),'server_boot_time':subprocess.check_output(['uptime','-s'],text=True).strip(),'prior_configuration_files_equal':True,'files':files,'commands':commands,'credential_hashes':credentials,'services_before':services,'interrupted_public_files':partial_files,'completed_upload_verified':True,'server_network_writes':False}
out.parent.mkdir(mode=0o700,exist_ok=True);out.write_text(json.dumps(report,indent=2)+'\n');out.chmod(0o600);print(json.dumps(report))
PY
